-- Alternative to CSV import. Run after 01_create_users.sql.
-- !dummy-no-login is a non-login placeholder, NOT a valid password hash.
-- Use for SELECT/CRUD lessons only. Before login lessons, replace it with
-- real Argon2 hashes generated by your backend's PasswordHash.recommended().
-- Re-running skips existing emails and preserves existing records.
BEGIN;
ON CONFLICT (email) DO NOTHING;
COMMIT;

SELECT id, name, email FROM public.users ORDER BY id;
SELECT count(*) AS dummy_user_count FROM public.users
WHERE email IN ('study.user001@example.com', 'study.user002@example.com', 'study.user003@example.com', 'study.user004@example.com', 'study.user005@example.com', 'study.user006@example.com', 'study.user007@example.com', 'study.user008@example.com', 'study.user009@example.com', 'study.user010@example.com', 'study.user011@example.com', 'study.user012@example.com', 'study.user013@example.com', 'study.user014@example.com', 'study.user015@example.com', 'study.user016@example.com', 'study.user017@example.com', 'study.user018@example.com', 'study.user019@example.com', 'study.user020@example.com', 'study.user021@example.com', 'study.user022@example.com', 'study.user023@example.com', 'study.user024@example.com', 'study.user025@example.com', 'study.user026@example.com', 'study.user027@example.com', 'study.user028@example.com', 'study.user029@example.com', 'study.user030@example.com');
